func:
/**
 * PIR Intermediário - versão simplificada com logs melhorados e reativação por lux corrigida
 *
 * Entradas:
 * - msg.payload: "on" / "off"  (PIR / presença)
 * - msg.lux: number            (leitura do sensor de luminosidade)
 * - msg.desativa: bool         (desabilitar automação)
 * - msg.manual: true           (acionamento manual externo)
 *
 * Saídas:
 * [0] ON
 * [1] OFF
 * [2] DEBUG (quando dbg=true)
 *
 * Variáveis de ambiente:
 * - lux_min        : não liga PIR se lux >= lux_min (0 = desativado)
 * - lux_max        : desliga PIR se lux >= lux_max enquanto ligado (0 = desativado)
 * - lux_max_manual : desliga modo manual se lux >= lux_max_manual (0 = desativado)
 * - t_off_s        : tempo de espera antes de desligar após PIR off ou lux alto (segundos)
 * - t_max_on_m     : tempo máximo ligado em modo PIR (minutos)
 * - dbg            : habilita debug (true/false)
 */

const cfg = {
  lux_min:        Number(env.get('lux_min')        || 0),
  lux_max:        Number(env.get('lux_max')        || 0),
  lux_max_manual: Number(env.get('lux_max_manual') || 0),
  t_off_s:        Number(env.get('t_off_s')        || 30),
  t_max_on_m:     Number(env.get('t_max_on_m')     || 60),
  dbg:            String(env.get('dbg'))            === 'true'
};

let state = context.get('state') || {
  light_on:           false,
  mode:               'off',   // off | pir | manual
  lux:                null,
  disabled:           false,
  pir_active:         false,
  last_pir:           0,
  pending_pir:        false,
  pending_reactivate: false    // verdadeiro quando luz foi desligada por lux_max com PIR ainda ativo
};

let timers = context.get('timers') || {};

function save() {
  context.set('state', state);
  context.set('timers', timers);
}

function log(msg) {
  if (!cfg.dbg) return;
  node.send([null, null, { payload: '[PIR] ' + msg }]);
}

function clearTimer(name) {
  if (timers[name]) {
    clearTimeout(timers[name]);
    delete timers[name];
  }
}

function setTimer(name, ms, fn) {
  clearTimer(name);
  timers[name] = setTimeout(fn, ms);
  log('timer [' + name + '] agendado: ' + (ms / 1000) + 's');
}

function turnOn(reason) {
  state.light_on           = true;
  state.mode               = 'pir';
  state.pending_pir        = false;
  state.pending_reactivate = false;

  clearTimer('off');
  setTimer('max_on', cfg.t_max_on_m * 60000, function () {
    log('timer [max_on] expirou (' + cfg.t_max_on_m + 'min) -> OFF');
    var fresh = context.get('state') || state;
    state = fresh;
    turnOff('max_on');
  });

  node.send([{ payload: 'on', reason: reason }, null, null]);
  log('ON | motivo: ' + reason + ' | lux: ' + state.lux + ' | pir_active: ' + state.pir_active);
  save();
}

function turnOff(reason) {
  state.light_on  = false;
  state.mode      = 'off';
  state.pending_pir = false;
  // NOTE: pending_reactivate is intentionally NOT cleared here;
  // the caller is responsible for setting it as needed before/after turnOff.

  clearTimer('off');
  clearTimer('max_on');

  node.send([null, { payload: 'off', reason: reason }, null]);
  log('OFF | motivo: ' + reason + ' | lux: ' + state.lux + ' | pir_active: ' + state.pir_active);
  save();
}

function clearPendingFlags(source) {
  if (state.pending_pir) {
    state.pending_pir = false;
    log('pending_pir cancelado por ' + source);
  }
  if (state.pending_reactivate) {
    state.pending_reactivate = false;
    log('pending_reactivate cancelado por ' + source);
  }
}

function handleLux(luxValue) {
  const lux = Number(luxValue);
  if (isNaN(lux)) return;

  const prev = state.lux;
  state.lux = lux;

  // Só loga lux quando há estado relevante ativo
  if (cfg.dbg && (state.light_on || state.pending_pir || state.pending_reactivate || state.pir_active)) {
    log('lux: ' + prev + ' -> ' + lux +
        ' | mode: ' + state.mode +
        ' | light_on: ' + state.light_on +
        ' | pir_active: ' + state.pir_active +
        ' | pending_pir: ' + state.pending_pir +
        ' | pending_reactivate: ' + state.pending_reactivate);
  }

  // --- Modo PIR ligado: monitora lux_max ---
  if (state.light_on && state.mode === 'pir' && cfg.lux_max > 0) {
    if (lux >= cfg.lux_max) {
      // Lux subiu acima do limite -> agenda desligamento se ainda não agendado
      if (!timers['off']) {
        log('lux ' + lux + ' >= lux_max ' + cfg.lux_max + ' -> agendando OFF em ' + cfg.t_off_s + 's');
        setTimer('off', cfg.t_off_s * 1000, function () {
          // Re-lê estado do contexto para evitar stale closure
          var fresh = context.get('state') || state;
          var pirActive = fresh.pir_active;
          state = fresh;
          log('timer [off/lux_max] expirou -> OFF (pir_active=' + pirActive + ')');
          turnOff('lux_max');
          // Se PIR ainda ativo, marca para religar quando lux baixar (abaixo de lux_max)
          if (pirActive) {
            state.pending_reactivate = true;
            context.set('state', state);
            log('PIR ainda ativo -> pending_reactivate=true (aguardando lux < lux_max para religar)');
          }
        });
      }
    } else {
      // Lux voltou abaixo de lux_max -> cancela timer de desligamento por lux, luz permanece acesa
      if (timers['off']) {
        log('lux ' + lux + ' < lux_max ' + cfg.lux_max + ' -> cancelando timer de desligamento por lux');
        clearTimer('off');
      }
    }
  }

  // --- Modo manual ligado: monitora lux_max_manual ---
  if (state.light_on && state.mode === 'manual' && cfg.lux_max_manual > 0) {
    if (lux >= cfg.lux_max_manual) {
      if (!timers['off']) {
        log('lux ' + lux + ' >= lux_max_manual ' + cfg.lux_max_manual + ' -> agendando OFF manual em ' + cfg.t_off_s + 's');
        setTimer('off', cfg.t_off_s * 1000, function () {
          var fresh = context.get('state') || state;
          state = fresh;
          log('timer [off/lux_max_manual] expirou -> OFF');
          turnOff('lux_max_manual');
        });
      }
    }
  }

  // --- pending_pir: PIR foi bloqueado por lux alto (>= lux_min), liga quando escurecer abaixo de lux_min ---
  if (state.pending_pir && state.pir_active && !state.light_on && cfg.lux_min > 0) {
    const age = Date.now() - state.last_pir;
    log('pending_pir: lux ' + lux + ' vs lux_min ' + cfg.lux_min + ' | idade PIR: ' + Math.round(age / 1000) + 's');
    if (age < 120000) {
      if (lux < cfg.lux_min) {
        log('lux ' + lux + ' < lux_min ' + cfg.lux_min + ' e pending_pir ativo -> ligando');
        turnOn('pending_lux');
        return;
      }
    } else {
      log('pending_pir expirou (>120s) -> limpo');
      state.pending_pir = false;
    }
  }

  // --- pending_reactivate: luz foi desligada por lux_max com PIR ainda ativo ---
  // Religa quando lux cair abaixo de lux_max (o limiar que causou o desligamento)
  if (state.pending_reactivate && state.pir_active && !state.light_on) {
    // Usa lux_max como threshold de reativação (foi o limiar que causou o desligamento)
    // Se lux_max não configurado, usa lux_min como fallback
    const threshold = cfg.lux_max > 0 ? cfg.lux_max : (cfg.lux_min > 0 ? cfg.lux_min : 0);
    if (threshold > 0) {
      log('pending_reactivate: lux ' + lux + ' vs threshold ' + threshold +
          ' (lux_max=' + cfg.lux_max + ')');
      if (lux < threshold) {
        log('lux ' + lux + ' < threshold ' + threshold + ' -> religando (PIR ainda ativo)');
        turnOn('reactivate_lux');
        return;
      }
    }
  }

  save();
}

function handleDesativa(val) {
  const prev = state.disabled;
  state.disabled = !!val;

  if (prev !== state.disabled) {
    log('desativa: ' + prev + ' -> ' + state.disabled + ' | mode: ' + state.mode);
  }

  if (state.disabled && state.light_on && state.mode === 'pir') {
    log('desativa=true enquanto acesa em modo PIR -> agendando OFF em ' + cfg.t_off_s + 's');
    setTimer('off', cfg.t_off_s * 1000, function () {
      var fresh = context.get('state') || state;
      state = fresh;
      log('timer [off/desativa] expirou -> OFF');
      turnOff('disabled');
    });
  }

  if (state.disabled) {
    clearPendingFlags('desativa');
  }

  save();
}

function handleManual() {
  log('MANUAL ON | mode anterior: ' + state.mode);
  state.light_on           = true;
  state.mode               = 'manual';
  state.pending_pir        = false;
  state.pending_reactivate = false;

  clearTimer('off');
  clearTimer('max_on');

  save();
}

function handlePirOn() {
  state.pir_active = true;
  state.last_pir   = Date.now();

  log('PIR ON | mode: ' + state.mode +
      ' | light_on: ' + state.light_on +
      ' | lux: ' + state.lux +
      ' | disabled: ' + state.disabled);

  if (state.mode === 'manual') {
    log('PIR ON ignorado (modo manual)');
    save();
    return;
  }

  if (state.disabled) {
    log('PIR ON bloqueado (desativado)');
    save();
    return;
  }

  // Verifica lux_min: se ambiente claro demais, não liga agora mas marca pendente
  if (cfg.lux_min > 0 && state.lux !== null && state.lux >= cfg.lux_min) {
    log('PIR ON bloqueado por lux: ' + state.lux + ' >= lux_min ' + cfg.lux_min + ' -> pending_pir=true');
    state.pending_pir = true;
    save();
    return;
  }

  if (!state.light_on) {
    log('PIR ON -> ligando | lux: ' + state.lux);
    turnOn('pir');
  } else {
    // Luz já ligada: cancela timer de desligamento se PIR voltou (presença renovada)
    if (timers['off']) {
      log('PIR ON com luz já ligada -> cancelando timer off (presença renovada)');
      clearTimer('off');
    }
    save();
  }
}

function handlePirOff() {
  state.pir_active = false;
  clearPendingFlags('PIR_OFF');

  log('PIR OFF | mode: ' + state.mode +
      ' | light_on: ' + state.light_on +
      ' | lux: ' + state.lux);

  if (state.mode === 'manual') {
    log('PIR OFF ignorado (modo manual)');
    save();
    return;
  }

  if (state.light_on) {
    log('PIR OFF -> agendando desligamento em ' + cfg.t_off_s + 's');
    setTimer('off', cfg.t_off_s * 1000, function () {
      var fresh = context.get('state') || state;
      state = fresh;
      log('timer [off/pir_timeout] expirou -> OFF');
      turnOff('pir_timeout');
    });
  }

  save();
}

// === Roteamento principal ===
if (msg.lux !== undefined) {
  handleLux(msg.lux);
  return;
}

if (msg.desativa !== undefined) {
  handleDesativa(msg.desativa);
  return;
}

if (msg.manual === true) {
  handleManual();
  return;
}

if (msg.payload === 'on') {
  handlePirOn();
  return;
}

if (msg.payload === 'off') {
  handlePirOff();
  return;
}

save();
return;
